{ "results": [ { "title": "孔教論（陳煥章／孔教會）", "verdict": "partial", "issue": "Publication year often given as 1912 for Kongjiao Hui activity, but Kongjiao Lun text history needs check: two-essay structure may be accurate; verify exact 1912 imprint vs later printings." }, { "title": "易筋经（master）", "verdict": "partial", "issue": "Attribution to 紫凝道人 is one scholarly view among several; classic is traditionally attributed to Bodhidharma / later redacted; not solely 紫凝 with 般剌密谛 pairing as primary." }, { "title": "烟波钓叟歌", "verdict": "partial", "issue": "Authorship disputed; commonly transmitted as Song-era anonymous or 烟波钓叟, Ming 罗通 revisions exist but '北宋通人原作；明罗通增删' is a specific chain that may overstate certainty." } ] }{ "results": [ { "title": "sample", "verdict": "partial", "issue": "placeholder" } ] }{
  "results": [
    {
      "title": "起土開金井刈鬮科儀（台灣閭山小法）",
      "verdict": "partial",
      "issue": "Chinese title 刈鬮 (cắt thẻ/thăm) is fine, but Vietnamese gloss “ngải cữu” evokes 艾灸 and misleads; content description of Lushan earth-opening/grave rites is otherwise plausible."
    },
    {
      "title": "台湾道教仪式之音乐（吕锤宽）",
      "verdict": "inaccurate",
      "issue": "No attested Lu Chuikuan monograph under this exact title. His well-documented book is 《臺灣的道教儀式與音樂》(1994); this looks like a confabulated variant of that title."
    },
    {
      "title": "道教仪式的音乐学研究（吕锤宽）",
      "verdict": "inaccurate",
      "issue": "No evidence Lu authored a work titled 《道教仪式的音乐学研究》. Related real titles include 《臺灣的道教儀式與音樂》 and 《道教儀式與音樂之神聖性與世俗化》."
    },
    {
      "title": "台湾道教资料（大渊忍尔 采集）",
      "verdict": "inaccurate",
      "issue": "No standard Ofuchi publication titled 《台湾道教资料》. His Taiwan fieldwork/ritual texts appear mainly in 《中国人の宗教儀礼》(1983; Daoist section later reissued), not as a separate corpus under this Chinese title."
    },
    {
      "title": "易筋经（master）",
      "verdict": "partial",
      "issue": "Ming–Qing Daoist qigong character and 托名达摩 are sound; 紫凝道人 authorship is a major scholarly hypothesis (唐豪 etc.) but remains contested, and 般剌密谛 is part of the legend frame rather than a historical co-author."
    },
    {
      "title": "疑龙经",
      "verdict": "inaccurate",
      "issue": "Yilong Jing is a form/xingshi classic (branches of the dragon, face vs back, ending of the form). It does not analyze 玄空; inserting xuankong into its core content is a factual mix-up with later liqi schools."
    },
    {
      "title": "冰鉴",
      "verdict": "partial",
      "issue": "Widely marketed as Zeng Guofan’s physiognomy, but scholarship notes anonymous pre-Zeng manuscripts, family denial, and rival attributions (e.g. 罗祖真人). Popular attribution is not secure fact."
    },
    {
      "title": "相理衡真",
      "verdict": "inaccurate",
      "issue": "Wrong author: Qing author is 陈钊 (字淡野 / 虚虚子, Daoguang era), not 陈剑峰. Title and program of “衡真” match 陈钊’s work."
    },
    {
      "title": "水镜集",
      "verdict": "inaccurate",
      "issue": "Circulating 水镜/神相水镜集 tradition is a Qing–Republican physiognomy compilation (e.g. 范文园/范騋《神相水镜集》), not a Xu Fu–line master text. “传许负系” misattributes the known title."
    }
  ]
}
